package at.andrew.squashtap;
import org.junit.Test;
import static org.junit.Assert.*;
import java.time.LocalDate;
import java.util.*;

public class MultisportTest {
    private static void points(ScoreState s,int side,int n){for(int i=0;i<n;i++)assertTrue(s.add(side));}
    private static void game(ScoreState s,int side){points(s,side,4);}
    private static MatchState match(String sport){return new MatchState(UUID.randomUUID().toString(),3,MatchFormat.defaults(sport));}
    @Test public void everyFormatRoundTrips(){for(String sport:MatchFormat.SPORTS){MatchFormat f=MatchFormat.defaults(sport);assertEquals(f,MatchFormat.decode(f.encode()));assertEquals(sport,MatchState.decode(new MatchState("test",3,f).encode()).format().sport);}}
    @Test public void oldSquashEncodingStaysIdentical(){MatchState m=new MatchState("old",3);m.add(0);assertTrue(m.encode().startsWith("M1|"));assertEquals(m.encode(),MatchState.decode(m.encode()).encode());assertTrue(new MatchBook(m).encode().startsWith("B4:"));}
    @Test public void badmintonBothCaps(){for(int target:new int[]{15,21}){MatchFormat f=MatchFormat.defaults("badminton").target(target);ScoreState s=new ScoreState(f,false);for(int i=0;i<f.cap()-1;i++){assertTrue(s.add(0));assertTrue(s.add(1));}assertEquals(-1,s.winner());assertTrue(s.add(1));assertEquals(1,s.winner());assertFalse(s.add(0));assertTrue(s.undo());assertEquals(-1,s.winner());assertEquals(s.encode(),ScoreState.decode(s.encode()).encode());}}
    @Test public void badmintonWinningByTwo(){ScoreState s=new ScoreState(MatchFormat.defaults("badminton").target(15),false);for(int i=0;i<14;i++){s.add(0);s.add(1);}s.add(0);assertEquals(-1,s.winner());s.add(0);assertEquals(0,s.winner());}
    @Test public void tennisPointLabelsAndGameReset(){ScoreState s=new ScoreState(MatchFormat.defaults("tennis"),false);assertEquals("0",s.displayPoint(0));s.add(0);assertEquals("15",s.displayPoint(0));s.add(0);assertEquals("30",s.displayPoint(0));s.add(0);assertEquals("40",s.displayPoint(0));s.add(0);assertEquals(1,s.blue());assertEquals("0",s.displayPoint(0));s.undo();assertEquals(0,s.blue());assertEquals("40",s.displayPoint(0));}
    @Test public void advantageCanRepeat(){ScoreState s=new ScoreState(MatchFormat.defaults("tennis"),false);points(s,0,3);points(s,1,3);for(int i=0;i<20;i++){s.add(0);assertEquals("AD",s.displayPoint(0));s.add(1);assertEquals(0,s.blue());}points(s,1,2);assertEquals(1,s.red());}
    @Test public void noAdDecidesAtFirstDeuce(){ScoreState s=new ScoreState(MatchFormat.defaults("tennis").deuce("no-ad"),false);points(s,0,3);points(s,1,3);s.add(1);assertEquals(1,s.red());assertEquals(0,s.blue());}
    @Test public void starPointAtThirdDeuceAndUndo(){ScoreState s=new ScoreState(MatchFormat.defaults("padel"),false);points(s,0,3);points(s,1,3);for(int i=0;i<2;i++){s.add(0);s.add(1);}assertEquals("DECIDING POINT",s.status());assertEquals(0,s.blue());s.add(1);assertEquals(1,s.red());s.undo();assertEquals("DECIDING POINT",s.status());assertEquals(s.encode(),ScoreState.decode(s.encode()).encode());}
    @Test public void sixFourSevenFiveAndTieBreak(){for(int loser:new int[]{0,4,5,6})assertTrue(ScoreState.finalScore(MatchFormat.defaults("tennis"),false,loser<5?6:7,loser));assertFalse(ScoreState.finalScore(MatchFormat.defaults("tennis"),false,6,5));ScoreState s=new ScoreState(MatchFormat.defaults("tennis"),false);for(int i=0;i<6;i++){game(s,0);game(s,1);}assertEquals(-1,s.winner());for(int i=0;i<6;i++){s.add(0);s.add(1);}points(s,1,2);assertEquals(1,s.winner());assertEquals(7,s.red());assertEquals(6,s.blue());assertEquals(8,s.tiePoints(1));s.undo();assertEquals(-1,s.winner());assertEquals(6,s.red());}
    @Test public void finalMatchTieBreak(){MatchFormat f=MatchFormat.defaults("tennis").finalTie(true);MatchState m=new MatchState("tie",3,f);m.enterCompletedSet(6,0);m.enterCompletedSet(0,6);assertTrue(m.nextGame());assertTrue(m.game().matchTie());for(int i=0;i<9;i++){m.add(0);m.add(1);}m.add(0);assertFalse(m.complete());m.add(0);assertTrue(m.complete());assertEquals(0,m.winner());assertTrue(MatchResult.from(m,"2026-11-10",1).gamesText().contains("Match tie-break"));}
    @Test public void allFormatsBookPersistence(){for(String sport:MatchFormat.SPORTS){MatchBook book=new MatchBook(match(sport));int score=book.current().format().nested()?6:book.current().format().target;book.enterCompletedSet(score,0);book.enterCompletedSet(score,1);String encoded=book.encode();MatchBook copy=MatchBook.decode(encoded);assertEquals(encoded,copy.encode());assertEquals(sport,copy.newestFirst().get(0).format.sport);assertTrue(copy.undo());assertEquals(0,copy.count());}}
    @Test public void tableTennisSevenGames(){MatchState m=new MatchState("seven",7,MatchFormat.defaults("table-tennis"));for(int i=0;i<6;i++)m.enterCompletedSet(i%2==0?11:0,i%2==0?0:11);m.enterCompletedSet(11,3);assertTrue(m.complete());MatchBook b=new MatchBook(m);b.saveCompleted(LocalDate.now());assertEquals(7,MatchBook.decode(b.encode()).newestFirst().get(0).gameCount());}
    @Test public void summaryPointsAreNotInvented(){MatchState m=match("tennis");m.enterCompletedSet(6,0);m.enterCompletedSet(6,0);MatchResult r=MatchResult.from(m,"2026-11-10",1);assertEquals(-1,r.rallyPoints(0,0));MatchStatistics stats=MatchStatistics.from(Arrays.asList(r));assertEquals(0,stats.pointsPlayed());assertEquals(12,stats.gamesFor);assertEquals(1,stats.unknownPointMatches);}
    @Test public void tennisRecordedPointTotalsSurvive(){MatchState m=match("tennis");for(int set=0;set<2;set++){for(int i=0;i<6;i++)game(m.game(),0);if(set==0)m.nextGame();}MatchResult r=MatchResult.from(m,"2026-11-10",1);assertEquals(24,r.rallyPoints(0,0));assertEquals(48,MatchStatistics.from(Arrays.asList(r)).pointsFor);}
    @Test public void multiplayerCsvRoundTripAndIcons(){OpponentDirectory d=new OpponentDirectory();String a=d.add("Jane"),b=d.add("Bob"),c=d.add("Pat");MatchState m=new MatchState("doubles",3,MatchFormat.defaults("badminton").mode(true));m.enterCompletedSet(21,10);m.enterCompletedSet(21,5);MatchResult r=MatchResult.from(m,"2026-11-10",1);d.assignTeam(m.id(),a,b,c);String csv=MatchCsv.export(Arrays.asList(r),d);assertTrue(csv.contains("sport,mode,rules"));MatchCsv.Row row=MatchCsv.parse(csv).get(0);assertEquals(b,row.partnerId);assertEquals(c,row.otherId);assertEquals(r.format,row.result.format);assertEquals(new HashSet<>(Arrays.asList("badminton")),d.sportsFor(b,Arrays.asList(r)));assertTrue(d.involved(m.id(),b));assertEquals(d.encode(),OpponentDirectory.decode(d.encode()).encode());}
    @Test public void mixedCsvAndReimportRetainsMetadata(){MatchState tennis=match("tennis");tennis.enterCompletedSet(6,1);tennis.enterCompletedSet(7,5);MatchResult a=MatchResult.from(tennis,"2026-11-10",1);MatchState squash=match("squash");squash.enterCompletedSet(11,4);squash.enterCompletedSet(11,2);MatchResult b=MatchResult.from(squash,"2026-11-10",2);String csv=MatchCsv.export(Arrays.asList(a,b),new OpponentDirectory());assertEquals(2,MatchCsv.parse(csv).size());MatchCsv.Plan plan=MatchCsv.plan(new MatchBook(new MatchState("current",3)),new OpponentDirectory(),MatchCsv.parse(csv));assertEquals(2,plan.added);assertEquals("tennis",plan.book.result(a.id).format.sport);assertEquals(2,MatchCsv.plan(plan.book,plan.directory,MatchCsv.parse(csv)).duplicates);}
    @Test public void squashServerFollowsRallyAndUndo(){MatchState m=match("squash");assertEquals(-1,m.server());m.serving(1,-1);assertEquals(1,m.server());m.add(0);assertEquals(0,m.server());m.add(1);assertEquals(1,m.server());m.undo();assertEquals(0,m.server());assertEquals(m.encode(),MatchState.decode(m.encode()).encode());}
    @Test public void tennisServerRotatesOnGames(){MatchState m=match("tennis");m.serving(0,-1);assertEquals(0,m.server());game(m.game(),0);assertEquals(1,m.server());m.undo();assertEquals(0,m.server());}
    @Test public void tableTennisServiceAndDeuce(){MatchState m=match("table-tennis");m.serving(0,-1);for(int i=0;i<10;i++){assertEquals((i%2==0?0:1),m.server());m.add(0);m.add(1);}assertEquals(0,m.server());m.add(0);assertEquals(1,m.server());m.add(1);assertEquals(0,m.server());m.undo();assertEquals(1,m.server());}
    @Test public void doublesTableTennisRotation(){MatchState m=new MatchState("doubles",3,MatchFormat.defaults("table-tennis").mode(true));m.serving(0,1);assertEquals(0,m.server());m.add(0);m.add(1);assertEquals(1,m.server());m.add(0);m.add(1);assertEquals(2,m.server());}
    @Test public void doublesBadmintonRotation(){MatchState m=new MatchState("double-bad",3,MatchFormat.defaults("badminton").mode(true));m.serving(0,1);assertEquals(0,m.server());m.add(0);assertEquals(0,m.server());m.add(1);assertEquals(3,m.server());m.add(1);assertEquals(3,m.server());m.add(0);assertEquals(2,m.server());}
    @Test public void gameAndMatchBall(){MatchState m=match("squash");points(m.game(),0,10);assertEquals(0,m.game().gameBall());points(m.game(),1,10);assertEquals(-1,m.game().gameBall());m.add(1);assertEquals(1,m.game().gameBall());}
    @Test public void noDuplicatePeople(){OpponentDirectory d=new OpponentDirectory();String id=d.add("Same person");try{d.assignTeam("m",id,id,"");fail();}catch(IllegalArgumentException expected){}assertEquals("",d.opponentId("m"));}
    @Test public void invalidRulesRejected(){for(String invalid:new String[]{"padel,0,6,star,0","squash,1,11,advantage,0","badminton,0,21,star,0","tennis,0,11,advantage,0"})try{MatchFormat.decode(invalid);fail(invalid);}catch(IllegalArgumentException expected){}}
    @Test public void decidingTableTennisGameReversesReceivingOrderAtFive(){MatchState m=new MatchState("decider",3,MatchFormat.defaults("table-tennis").mode(true));m.enterCompletedSet(11,0);m.enterCompletedSet(0,11);m.nextGame();m.serving(0,1);for(int i=0;i<4;i++){m.add(0);m.add(1);}m.add(0);assertEquals(0,m.server());m.add(1);assertEquals(3,m.server());m.undo();assertEquals(0,m.server());}
    @Test public void playerBadgesDisappearWithDeletedOrReopenedResults(){MatchBook b=new MatchBook(match("badminton"));b.enterCompletedSet(21,0);b.enterCompletedSet(21,1);OpponentDirectory d=new OpponentDirectory();String person=d.add("Player");d.assign(b.current().id(),person);assertTrue(d.sportsFor(person,b.newestFirst()).contains("badminton"));b.undo();assertTrue(d.sportsFor(person,b.newestFirst()).isEmpty());b.enterCompletedSet(21,1);b.delete(b.current().id());assertTrue(d.sportsFor(person,b.newestFirst()).isEmpty());}
    @Test public void roleMetadataCannotAliasAnotherMatchId(){OpponentDirectory d=new OpponentDirectory();String a=d.add("A"),b=d.add("B"),c=d.add("C");d.assignTeam("one",a,b,c);d.assign("two",c);OpponentDirectory copy=OpponentDirectory.decode(d.encode());assertTrue(d.encode().startsWith("O2:"));assertEquals(c,copy.opponentId("two"));assertEquals(b,copy.roleId("one",1));assertEquals(c,copy.roleId("one",2));}
    @Test public void retirementRetainsPartialTennisGamePoints(){MatchState m=match("tennis");for(int i=0;i<3;i++)m.add(0);m.add(1);m.retire(1);MatchResult r=MatchResult.from(m,"2026-11-10",1);assertEquals(3,r.unfinishedPoints(0,0));assertTrue(r.gamesText().contains("points 40–15"));MatchBook b=new MatchBook(m);b.saveCompleted(LocalDate.now());assertEquals(3,MatchBook.decode(b.encode()).result(m.id()).unfinishedPoints(0,0));assertEquals(3,MatchCsv.parse(MatchCsv.export(Arrays.asList(r),new OpponentDirectory())).get(0).result.unfinishedPoints(0,0));}
    @Test public void tableTennisServiceContinuesBetweenGames(){MatchState m=match("table-tennis");m.serving(0,-1);m.enterCompletedSet(11,3);m.nextGame();assertEquals(1,m.server());MatchState d=new MatchState("double-next",3,MatchFormat.defaults("table-tennis").mode(true));d.serving(2,3);d.enterCompletedSet(11,0);d.nextGame();assertEquals(3,d.server());assertEquals(2,d.firstReceiver(1));}
    public static void main(String[] args)throws Exception{
        if(args.length>0){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=System.in.read(buf))!=-1)out.write(buf,0,n);java.util.List<MatchCsv.Row> rows=MatchCsv.parse(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));System.out.print(rows.size()+":"+rows.get(0).result.format.sport+":"+rows.get(0).result.format.target);return;}
        java.util.List<MatchResult> results=new java.util.ArrayList<>();OpponentDirectory d=new OpponentDirectory();String jane=d.add("Jane"),bob=d.add("Bob"),pat=d.add("Pat");
        for(String sport:MatchFormat.SPORTS){MatchFormat f=MatchFormat.defaults(sport);if(sport.equals("badminton"))f=f.target(15).mode(true);MatchState m=new MatchState("fixture-"+sport,3,f);int target=f.nested()?6:f.target;m.enterCompletedSet(target,0);m.enterCompletedSet(target,1);MatchResult r=MatchResult.from(m,"2026-11-10",results.size()+1);results.add(r);if(f.doubles)d.assignTeam(m.id(),jane,bob,pat);else d.assign(m.id(),jane);}
        System.out.print(MatchCsv.export(results,d));
    }

}
